def seed_sponsor_categories(apps, schema_editor):
    """Create the requested editable sponsor categories without fake sponsors."""
    SponsorCategory = apps.get_model("partners", "SponsorCategory")
    database = schema_editor.connection.alias
    categories = (
        ("Title Sponsor", "title-sponsor"),
        ("Co-Sponsors", "co-sponsors"),
        ("Platinum Sponsors", "platinum-sponsors"),
        ("Gold Sponsors", "gold-sponsors"),
        ("Strategic Partners", "strategic-partners"),
        ("Media Partners", "media-partners"),
    )
    for display_order, (name, slug) in enumerate(categories, start=1):
        SponsorCategory.objects.using(database).get_or_create(
            slug=slug,
            defaults={"name": name, "display_order": display_order},
        )


